                            continue
                        nc = route_cost(na) + route_cost(nb)
                        gain = (base_a + base_b) - nc
                        if gain > 1e-12 and (best is None or gain > best[0] + 1e-12):
                            best = (gain, na, nb)
                if best is not None:
                    routes[a] = best[1]
                    routes[b] = best[2]
                    improved = True
                    break
                # Swap
                for i, ca in enumerate(ra):
                    da = demand.get(ca, 0.0)
                    for j, cb in enumerate(rb):
                        db = demand.get(cb, 0.0)
                        new_load_a = load_a - da + db
                        new_load_b = load_b - db + da
                        if new_load_a > capacity + 1e-12 or new_load_b > capacity + 1e-12:
                            continue
                        na = ra[:i] + [cb] + ra[i + 1:]
                        nb = rb[:j] + [ca] + rb[j + 1:]
                        nc = route_cost(na) + route_cost(nb)
                        gain = (base_a + base_b) - nc
                        if gain > 1e-12:
                            routes[a] = na
                            routes[b] = nb
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

    # Final cleanup: ensure no empty routes
    routes = [r for r in routes if r]

    # Final feasibility safeguard: if any route still exceeds capacity, split it
    final_routes = []
    for route in routes:
        load = 0.0
        sub = []
        for cid in route:
            d = demand.get(cid, 0.0)
            if sub and load + d > capacity + 1e-12:
                final_routes.append(sub)
                sub = [cid]
                load = d
            else:
                sub.append(cid)
                load += d
        if sub:
            final_routes.append(sub)

    return final_routes
